// HasResource applies the HasEdge predicate on the "resource" edge.
func HasResource() predicate.EnterpriseResourceParty {
	return predicate.EnterpriseResourceParty(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ResourceTable, ResourceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasResourceWith applies the HasEdge predicate on the "resource" edge with a given conditions (other predicates).
func HasResourceWith(preds ...predicate.EnterpriseResource) predicate.EnterpriseResourceParty {
	return predicate.EnterpriseResourceParty(func(s *sql.Selector) {
		step := newResourceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EnterpriseResourceParty) predicate.EnterpriseResourceParty {
	return predicate.EnterpriseResourceParty(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EnterpriseResourceParty) predicate.EnterpriseResourceParty {
	return predicate.EnterpriseResourceParty(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EnterpriseResourceParty) predicate.EnterpriseResourceParty {
	return predicate.EnterpriseResourceParty(sql.NotPredicates(p))
}
